const files='abcdefgh', initial='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR';
export function start(){let b=Array(64).fill(null);initial.split('/').forEach((row,y)=>{let x=0;for(const c of row) if(/\d/.test(c))x+=+c;else b[y*8+x++]=c});return {b,turn:'w',ep:null};}
function white(p){return p===p.toUpperCase()}
function attack(s,from,to,p){let x=from%8,y=from>>3,X=to%8,Y=to>>3,dx=X-x,dy=Y-y,k=p.toLowerCase();if(k==='p')return Math.abs(dx)===1&&dy===(white(p)?-1:1);if(k==='n')return Math.abs(dx)*Math.abs(dy)===2;if(k==='k')return Math.max(Math.abs(dx),Math.abs(dy))===1;let straight=dx===0||dy===0,diag=Math.abs(dx)===Math.abs(dy);if(!((k==='r'&&straight)||(k==='b'&&diag)||(k==='q'&&(straight||diag))))return false;let sx=Math.sign(dx),sy=Math.sign(dy);for(let a=x+sx,b=y+sy;a!==X||b!==Y;a+=sx,b+=sy)if(s.b[b*8+a])return false;return true;}
function checked(s,w){let king=s.b.indexOf(w?'K':'k');if(king<0)return true;return s.b.some((p,i)=>p&&white(p)!==w&&attack(s,i,king,p));}
function play(s,from,to,promote){let n={b:s.b.slice(),turn:s.turn==='w'?'b':'w',ep:null},p=n.b[from],w=white(p);n.b[to]=p;n.b[from]=null;if(p.toLowerCase()==='p'){if(to===s.ep&&from%8!==to%8&&!s.b[to])n.b[to+(w?8:-8)]=null;if(Math.abs(to-from)===16)n.ep=(from+to)/2;if(promote)n.b[to]=w?promote.toUpperCase():promote.toLowerCase();}return n}
export function move(s,san){let token=san.replace(/[!?+#]+$/g,'').replace(/0/g,'O'),w=s.turn==='w';if(/^O-O(-O)?$/.test(token)){let long=token==='O-O-O',from=w?60:4,to=from+(long?-2:2),rook=from+(long?-4:3),rookTo=from+(long?-1:1);if(s.b[from]!==(w?'K':'k')||s.b[rook]!==(w?'R':'r'))throw Error('Invalid castling');let n=play(s,from,to);n.b[rookTo]=n.b[rook];n.b[rook]=null;return {state:n,from,to};}let m=token.match(/^([KQRBN])?([a-h]?)([1-8]?)(x?)([a-h][1-8])(?:=?([QRBN]))?$/);if(!m)throw Error('Unsupported move '+san);let [,piece='',file='',rank='',capture,dest,promo]=m,to=(8-Number(dest[1]))*8+files.indexOf(dest[0]),wanted=piece||'P',candidates=[];for(let i=0;i<64;i++){let p=s.b[i];if(!p||white(p)!==w||p.toUpperCase()!==wanted)continue;if(file&&files[i%8]!==file||rank&&String(8-(i>>3))!==rank)continue;let dx=(to%8)-(i%8),dy=(to>>3)-(i>>3),ok=false;if(wanted==='P'){let dir=w?-1:1;ok=capture?Math.abs(dx)===1&&dy===dir&&(!!s.b[to]||to===s.ep):dx===0&&!s.b[to]&&(dy===dir||(dy===2*dir&&(i>>3)===(w?6:1)&&!s.b[i+dir*8]));}else ok=attack(s,i,to,p);if(!ok||s.b[to]&&white(s.b[to])===w||capture&&!s.b[to]&&to!==s.ep||!capture&&!!s.b[to])continue;let next=play(s,i,to,promo);if(!checked(next,w))candidates.push({state:next,from:i,to});}if(candidates.length!==1)throw Error(`Cannot resolve ${san}: ${candidates.length} candidates`);return candidates[0]}
export function parsePGN(text){let chunks=text.replace(/\r/g,'').split(/(?=^\s*\[Event\s+")/m).filter(x=>x.trim());return chunks.map(chunk=>{let tags={};chunk.replace(/^\s*\[(\w+)\s+"((?:\\.|[^"\\])*)"\]\s*$/gm,(_,k,v)=>{tags[k]=v;return ''});let body=chunk.replace(/^\s*\[\w+\s+"(?:\\.|[^"\\])*"\]\s*$/gm,'');let depth=0,out='',comment=false,buf='';for(let i=0;i<body.length;i++){let c=body[i];if(comment){if(c==='}'){comment=false;if(depth===0)out+=' {'+buf+'} ';buf='';}else buf+=c;continue}if(c==='{'){comment=true;continue}if(c===';'){while(i<body.length&&body[i]!=='\n')i++;out+=' ';continue}if(c==='('){depth++;continue}if(c===')'){depth=Math.max(0,depth-1);continue}if(!depth)out+=c}let tokens=out.match(/\{[^}]*\}|[^\s]+/g)||[],moves=[];for(let raw of tokens){if(raw.startsWith('{')){let a=raw.match(/\[%clk\s+([^\]]+)\]/);if(a&&moves.length)moves[moves.length-1].clock=a[1];continue}let t=raw.replace(/^\d+\.{1,3}/,'').replace(/\$\d+/g,'');if(!t||/^\.+$/.test(t)||/^(1-0|0-1|1\/2-1\/2|\*)$/.test(t))continue;moves.push({san:t});}return {tags,moves};}).filter(g=>(g.moves.length||(/forfeit|default/i.test(g.tags.Termination||'')&&/^(1-0|0-1)$/.test(g.tags.Result||'')))&&(!g.tags.Variant||/^(standard|chess|normal)$/i.test(g.tags.Variant))&&!g.tags.FEN)}
export function prepare(g){let s=start(),positions=[{state:s,from:null,to:null,clocks:[null,null]}],clocks=[null,null];for(const [i,m] of g.moves.entries()){try{let p=move(s,m.san);s=p.state;if(m.clock)clocks[i%2]=m.clock;positions.push({...p,clocks:clocks.slice()})}catch(e){throw Error(`Move ${Math.floor(i/2)+1}${i%2?'...':'.'} ${m.san}: ${e.message}`)}}return {...g,positions}}
